create table if not exists public.order_installments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, payment_id uuid references public.payments(id) on delete set null, installment_number integer not null, due_date timestamptz, amount_due numeric not null check(amount_due>=0), amount_paid numeric not null default 0 check(amount_paid>=0), status text not null default 'pending' check(status in ('pending','partial','paid','overdue','cancelled')), payment_reference text, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(order_id,installment_number)); create index if not exists order_installments_order_idx on public.order_installments(order_id,installment_number); create or replace function public.build_order_installment_schedule(_order_id uuid,_months integer,_total_amount numeric,_start_date timestamptz default now()) returns void language plpgsql security definer set search_path=public as $$ declare i integer; base numeric; remainder numeric; begin if _months is null or _months<1 then raise exception 'Invalid installment months'; end if; if _total_amount<=0 then raise exception 'Invalid installment total'; end if; delete from public.order_installments where order_id=_order_id and amount_paid=0; base:=round(_total_amount/_months,2); remainder:=_total_amount-(base*_months); for i in 1.._months loop insert into public.order_installments(order_id,installment_number,due_date,amount_due) values(_order_id,i,_start_date+(i-1)*interval '1 month',case when i=_months then base+remainder else base end) on conflict(order_id,installment_number) do update set amount_due=excluded.amount_due,updated_at=now(); end loop; end; $$; revoke all on function public.build_order_installment_schedule(uuid,integer,numeric,timestamptz) from public; grant execute on function public.build_order_installment_schedule(uuid,integer,numeric,timestamptz) to authenticated; create or replace function public.record_order_installment_payment(_order_id uuid,_amount numeric,_reference text,_payment_id uuid default null) returns public.order_installments language plpgsql security definer set search_path=public as $$ declare r public.order_installments; remaining numeric; applied numeric; begin if _amount<=0 then raise exception 'Invalid installment amount'; end if; select coalesce(sum(amount_due-amount_paid),0) into remaining from public.order_installments where order_id=_order_id and status not in ('paid','cancelled'); if _amount>remaining then raise exception 'Installment payment exceeds outstanding balance'; end if; select * into r from public.order_installments where order_id=_order_id and status in ('pending','partial','overdue') order by installment_number for update limit 1; if r.id is null then raise exception 'No outstanding installment'; end if; applied:=least(_amount,r.amount_due-r.amount_paid); update public.order_installments set amount_paid=amount_paid+applied,status=case when amount_paid+applied>=amount_due then 'paid' else 'partial' end,payment_reference=_reference,payment_id=_payment_id,paid_at=case when amount_paid+applied>=amount_due then now() else paid_at end,updated_at=now() where id=r.id returning * into r; return r; end; $$; revoke all on function public.record_order_installment_payment(uuid,numeric,text,uuid) from public; grant execute on function public.record_order_installment_payment(uuid,numeric,text,uuid) to authenticated;
